labelExpressionInfo.expression:
// line break on this many words

var breakcount = 3

 

// split words

var s = split($feature["location_name"]," ")

var scount = count(s)

var lbl = ''

 

if (scount>breakcount) {

  for (var i = 1; i < count(s)+1; i++) {        // loop through the words

    lbl += s[i-1] + " ";                        // add word to label

    if ((i % breakcount == 0) && (i!=scount) && (i!=scount-1))    // if we have 3 words and not the last word and not one word left (orphan) add a linebreak

      { lbl += TextFormatting.NewLine}

  }

  return trim(lbl)}

// else no break needed  

else {return $feature["location_name"]}
